    /**
     * Tests getting all Disputes.
     *
     * @return    Collection
     */
    public List<Dispute> testGetAll() throws Throwable {
    LOGGER.info( "DisputeTest:testGetAll() - Retrieving Collection of Disputes:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Dispute : " );
    List<Dispute> collection  = null;

    try {
        // call the static get method on the DisputeService
        collection = service.getAllDispute();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Dispute currEntity  = null;
            Iterator<Dispute> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDisputeId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

